/* ui_font — tiny built-in alpha-bitmap UI font (DejaVu Sans, 11 px regular / 12 px bold, ASCII)
 * used for the labels the web edition draws with canvas text (select-window bank tree/heading) and
 * the Android shell's octave bar. Portable C++, no OS. Bitmaps are generated by tools/gen_font.py. */
#pragma once
#include <cstdint>
#include <string>

namespace synth1 {
namespace panel {

struct UiGlyph { int adv, x, y, w, h, off; };   // x,y = bearing from pen/baseline (y<0: above)
struct UiFont {
  const UiGlyph* glyphs;   // ASCII 32..126
  const unsigned char* data;
  int ascent, descent;
};

const UiFont& uiFontRegular();
const UiFont& uiFontBold();
/* Anti-aliased DejaVu Sans at 16/22/30/42/56 px: the nearest to px (device-resolution text). */
const UiFont& uiFontRegularPx(int px, int* actualPx = nullptr);
const UiFont& uiFontMonoBold();   // DejaVu Sans Mono Bold 10 px: the classic skin's label font
int uiTextWidth(const UiFont& f, const std::string& s);
/* Alpha-blend text (fg rgb) onto an RGBA buffer (w*h*4); (x, baseline) = pen origin; scale >= 1
 * replicates pixels. */
void uiDrawText(uint8_t* rgba, int w, int h, int x, int baseline, const std::string& s,
                const uint8_t fg[3], const UiFont& f, int scale = 1);

}   // namespace panel
}   // namespace synth1
